def max_subsequence(nums, k):
    stack = []
    drop = len(nums) - k
    for x in nums:
        while drop > 0 and stack and stack[-1] < x:            # monotonic stack, max subsequence
            stack.pop()
            drop -= 1
        stack.append(x)
    return stack[:k]

def greater(a, i, b, j):
    while i < len(a) and j < len(b):                              # compare FULL remaining suffixes
        if a[i] != b[j]:
            return a[i] > b[j]
        i += 1; j += 1
    return (len(a) - i) > (len(b) - j)

def merge(a, b):
    res = []
    i = j = 0
    while i < len(a) or j < len(b):
        if greater(a, i, b, j):                                      # take from the greater remaining suffix
            res.append(a[i]); i += 1
        else:
            res.append(b[j]); j += 1
    return res

def max_number(nums1, nums2, k):
    best = []
    for i in range(max(0, k - len(nums2)), min(k, len(nums1)) + 1):   # try every valid split
        candidate = merge(max_subsequence(nums1, i), max_subsequence(nums2, k - i))
        if greater(candidate, 0, best, 0):
            best = candidate
    return best

