import java.util.*;

public class Main {
    static int[] maxSubsequence(int[] nums, int k) {
        int[] stack = new int[k];
        int top = -1, drop = nums.length - k;
        for (int x : nums) {
            while (top >= 0 && drop > 0 && stack[top] < x) { top--; drop--; }    // monotonic stack
            if (top + 1 < k) stack[++top] = x;
            else drop--;
        }
        return stack;
    }

    static boolean greater(int[] a, int i, int[] b, int j) {
        while (i < a.length && j < b.length) {                                    // compare full suffixes
            if (a[i] != b[j]) return a[i] > b[j];
            i++; j++;
        }
        return (a.length - i) > (b.length - j);
    }

    static int[] merge(int[] a, int[] b) {
        int[] res = new int[a.length + b.length];
        int i = 0, j = 0, idx = 0;
        while (i < a.length || j < b.length) {
            if (greater(a, i, b, j)) res[idx++] = a[i++];                            // take from greater suffix
            else res[idx++] = b[j++];
        }
        return res;
    }

    static int[] maxNumber(int[] nums1, int[] nums2, int k) {
        int[] best = new int[0];
        for (int i = Math.max(0, k - nums2.length); i <= Math.min(k, nums1.length); i++) {   // try every split
            int[] candidate = merge(maxSubsequence(nums1, i), maxSubsequence(nums2, k - i));
            if (greater(candidate, 0, best, 0)) best = candidate;
        }
        return best;
    }
}

