#include <bits/stdc++.h>
using namespace std;

vector<int> maxSubsequence(vector<int>& nums, int k) {
    vector<int> stack;
    int drop = nums.size() - k;
    for (int x : nums) {
        while (drop > 0 && !stack.empty() && stack.back() < x) { stack.pop_back(); drop--; }  // monotonic stack
        stack.push_back(x);
    }
    stack.resize(k);
    return stack;
}

bool greaterSeq(vector<int>& a, int i, vector<int>& b, int j) {
    while (i < (int)a.size() && j < (int)b.size()) {                                             // compare full suffixes
        if (a[i] != b[j]) return a[i] > b[j];
        i++; j++;
    }
    return (int)(a.size() - i) > (int)(b.size() - j);
}

vector<int> mergeSeq(vector<int>& a, vector<int>& b) {
    vector<int> res;
    int i = 0, j = 0;
    while (i < (int)a.size() || j < (int)b.size()) {
        if (greaterSeq(a, i, b, j)) res.push_back(a[i++]);                                        // take from greater suffix
        else res.push_back(b[j++]);
    }
    return res;
}

vector<int> maxNumber(vector<int>& nums1, vector<int>& nums2, int k) {
    vector<int> best;
    for (int i = max(0, k - (int)nums2.size()); i <= min(k, (int)nums1.size()); i++) {           // try every split
        vector<int> sub1 = maxSubsequence(nums1, i), sub2 = maxSubsequence(nums2, k - i);
        vector<int> candidate = mergeSeq(sub1, sub2);
        if (greaterSeq(candidate, 0, best, 0)) best = candidate;
    }
    return best;
}
